import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import type {
  AppPunchFields,
  AppPunchRequest,
  AttendanceSource,
  ManualMarkReason,
  PunchFlag,
  PunchSource,
} from './types.js';

/** `attendance-protocol/fixtures/canonical.json`, generated by the Java `AppSignatures` tests. */
interface CanonicalFixture {
  punchVersion: string;
  envelopeVersion: string;
  noValue: string;
  punches: { name: string; input: AppPunchFields; canonical: string }[];
}

const fixture: CanonicalFixture = JSON.parse(
  readFileSync(fileURLToPath(new URL('../fixtures/canonical.json', import.meta.url)), 'utf8'),
);

/** Compile-time check: the fixture's punch inputs are exactly the ten signed fields. */
function asPunchFields(input: AppPunchFields): AppPunchFields {
  return input;
}

describe('attendance-protocol types', () => {
  it('fixture punch inputs have the shape of AppPunchFields', () => {
    expect(fixture.punchVersion).toBe('SKAT-PUNCH-1');
    expect(fixture.punches.length).toBeGreaterThan(0);
    for (const { input } of fixture.punches) {
      const fields = asPunchFields(input);
      expect(Object.keys(fields).sort()).toEqual(
        [
          'pairingId',
          'shopId',
          'employeeId',
          'punchId',
          'phoneTime',
          'offline',
          'locationChecked',
          'distanceMetres',
          'accuracyMetres',
          'mock',
        ].sort(),
      );
    }
  });

  it('a punch request is the signed fields plus one signature', () => {
    const request: AppPunchRequest = { ...fixture.punches[0].input, signature: 'MEUCIQ==' };
    // @ts-expect-error the phone never sends a direction; the server decides it (R4.9)
    const withDirection: AppPunchRequest = { ...request, direction: 'IN' };
    expect(withDirection.signature).toBe(request.signature);
  });

  it('string-literal unions carry the backend constants', () => {
    const sources: PunchSource[] = ['SELF', 'BIOMETRIC_APP', 'DEVICE_FILE', 'BRIDGE'];
    const flags: PunchFlag[] = [
      'OUTSIDE_SHOP',
      'LOW_ACCURACY',
      'NO_LOCATION',
      'LOCKED_PERIOD',
      'FAKE_LOCATION',
      'RECORDED_OFFLINE',
    ];
    const daySources: AttendanceSource[] = [
      'MANUAL',
      'BULK_PRESENT',
      'SELF_CHECK_IN',
      'BIOMETRIC_APP',
    ];
    const reasons: ManualMarkReason[] = [
      'FORGOT_PHONE',
      'PHONE_NOT_WORKING',
      'NO_NETWORK',
      'BIOMETRIC_NOT_WORKING',
      'OTHER',
    ];
    expect(sources).toContain('BIOMETRIC_APP');
    expect(flags).toContain('RECORDED_OFFLINE');
    expect(daySources).toContain('BIOMETRIC_APP');
    expect(reasons).toHaveLength(5);
  });
});
